def descriptive_statistics(df, metrics=("loc", "v(g)")):
    rows = []
    for metric in metrics:
        for grp, label in [(0, "Not Defective"), (1, "Defective")]:
            sub = df.loc[df["defects_bin"] == grp, metric]
            rows.append({
                "metric": metric,
                "group": label,
                "count": int(sub.count()),
                "mean": round(sub.mean(), 2),
                "median": round(sub.median(), 2),
                "min": round(sub.min(), 2),
                "max": round(sub.max(), 2),
                "std": round(sub.std(), 2),
            })
    return pd.DataFrame(rows)


desc_stats = descriptive_statistics(df, metrics=("loc", "v(g)"))
desc_stats

def correlation_analysis(df, metrics=("loc", "v(g)")):
    rows = []
    for metric in metrics:
        r, p = stats.pointbiserialr(df["defects_bin"], df[metric])
        rows.append({
            "metric": metric,
            "point_biserial_r": round(r, 4),
            "p_value": p,
            "significant_at_0.05": bool(p < 0.05),
            "direction": "positive (higher metric -> more defects)" if r > 0 else "negative",
        })
    return pd.DataFrame(rows)


correlations = correlation_analysis(df, metrics=("loc", "v(g)"))
correlations
